"""Core failure-hypothesis types for oracle-debug and main LLM modes."""

from __future__ import annotations

import re
from dataclasses import asdict, dataclass, fields
from typing import Any, Mapping

from src.data.labels import HANS_LABELS


_HYPOTHESIS_ID = re.compile(r"^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,127}$")


@dataclass(frozen=True)
class FailureHypothesis:
    id: str
    name: str
    description: str
    # ``heuristic`` is retained solely for the explicit HANS oracle/debug path.
    # It must be null for hypotheses generated by the main method.
    heuristic: str | None = None
    predicted_failure_behavior: str = ""
    predicted_failure_labels: tuple[str, ...] = ()
    verification_criteria: tuple[str, ...] = ()
    intervention_target: str = ""
    support_example_ids: tuple[str, ...] = ()
    source: str = "oracle_debug"
    prompt_version: str | None = None

    @classmethod
    def from_mapping(
        cls,
        value: Mapping[str, Any],
        *,
        require_llm_schema: bool = False,
    ) -> "FailureHypothesis":
        """Parse and validate one serialized hypothesis.

        Main-method artifacts use a deliberately strict schema.  Oracle
        artifacts from earlier milestones remain readable because their four
        original fields still have compatible defaults.
        """
        allowed = {field.name for field in fields(cls)}
        extra = set(value) - allowed
        if extra:
            raise ValueError(f"Unexpected hypothesis fields: {sorted(extra)}")
        if require_llm_schema:
            string_fields = (
                "id",
                "name",
                "description",
                "predicted_failure_behavior",
                "intervention_target",
                "source",
                "prompt_version",
            )
            if any(not isinstance(value.get(field), str) for field in string_fields):
                raise ValueError("Main-method hypothesis text fields must be strings")
            list_fields = (
                "predicted_failure_labels",
                "verification_criteria",
                "support_example_ids",
            )
            for field in list_fields:
                items = value.get(field)
                if not isinstance(items, (list, tuple)) or any(
                    not isinstance(item, str) for item in items
                ):
                    raise ValueError(f"Main-method hypothesis {field} must be a string list")
        try:
            hypothesis = cls(
                id=str(value["id"]),
                name=str(value["name"]),
                description=str(value["description"]),
                heuristic=(
                    None
                    if value.get("heuristic") is None
                    else str(value["heuristic"])
                ),
                predicted_failure_behavior=str(
                    value.get("predicted_failure_behavior", "")
                ),
                predicted_failure_labels=tuple(
                    str(item) for item in value.get("predicted_failure_labels", ())
                ),
                verification_criteria=tuple(
                    str(item) for item in value.get("verification_criteria", ())
                ),
                intervention_target=str(value.get("intervention_target", "")),
                support_example_ids=tuple(
                    str(item) for item in value.get("support_example_ids", ())
                ),
                source=str(value.get("source", "oracle_debug")),
                prompt_version=(
                    None
                    if value.get("prompt_version") is None
                    else str(value["prompt_version"])
                ),
            )
        except KeyError as exc:
            raise ValueError(
                f"Hypothesis is missing required field {exc.args[0]!r}"
            ) from exc
        hypothesis.validate(require_llm_schema=require_llm_schema)
        return hypothesis

    def validate(self, *, require_llm_schema: bool = False) -> None:
        if not _HYPOTHESIS_ID.fullmatch(self.id):
            raise ValueError(f"Invalid hypothesis id: {self.id!r}")
        if not self.name.strip() or not self.description.strip():
            raise ValueError("Hypothesis name and description must be non-empty")
        if len(set(self.support_example_ids)) != len(self.support_example_ids):
            raise ValueError("support_example_ids must be unique")
        invalid_labels = sorted(set(self.predicted_failure_labels) - set(HANS_LABELS))
        if invalid_labels:
            raise ValueError(
                f"Invalid predicted HANS failure labels: {invalid_labels}"
            )
        if not require_llm_schema:
            return
        if self.source != "llm_teacher":
            raise ValueError("Main-method hypotheses must use source='llm_teacher'")
        if self.heuristic is not None:
            raise ValueError(
                "Main-method hypotheses must not contain HANS heuristic metadata"
            )
        required_text = {
            "predicted_failure_behavior": self.predicted_failure_behavior,
            "intervention_target": self.intervention_target,
            "prompt_version": self.prompt_version or "",
        }
        missing = [name for name, text in required_text.items() if not text.strip()]
        if missing:
            raise ValueError(f"Main-method hypothesis fields are empty: {missing}")
        if not self.predicted_failure_labels:
            raise ValueError("At least one predicted failure label is required")
        if not self.verification_criteria:
            raise ValueError("At least one verification criterion is required")
        if any(not item.strip() for item in self.verification_criteria):
            raise ValueError("Verification criteria must be non-empty strings")
        if not self.support_example_ids:
            raise ValueError("At least one supporting discovery example is required")

    def to_dict(self) -> dict[str, Any]:
        if (
            self.source == "oracle_debug"
            and not self.predicted_failure_behavior
            and not self.predicted_failure_labels
            and not self.verification_criteria
            and not self.intervention_target
            and not self.support_example_ids
            and self.prompt_version is None
        ):
            # Preserve byte-level schema compatibility for legacy oracle files.
            return {
                "id": self.id,
                "name": self.name,
                "description": self.description,
                "heuristic": self.heuristic,
            }
        return asdict(self)
